const { Window } = require("happy-dom");
const fs = require("fs");
const path = require("path");

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.localStorage = null;
  }

  async loadApp() {
    const html = fs.readFileSync(
      path.resolve(__dirname, "..", "..", "index.html"),
      "utf-8"
    );
    const window = new Window();
    this.window = window;
    this.document = window.document;
    this.localStorage = window.localStorage;

    // Set up localStorage mock with data persistence
    this.document.write(html);

    // Load app JS
    const appJs = fs.readFileSync(
      path.resolve(__dirname, "..", "..", "js", "app.js"),
      "utf-8"
    );
    const scriptEl = this.document.createElement("script");
    scriptEl.textContent = appJs;
    this.document.body.appendChild(scriptEl);

    // Browser-like autofocus: focus the first element with autofocus attribute
    const autofocusEl = this.document.querySelector("[autofocus]");
    if (autofocusEl && typeof autofocusEl.focus === "function") {
      autofocusEl.focus();
    }

    // Wait for DOM to settle
    await new Promise((r) => setTimeout(r, 0));
  }

  reload() {
    // Re-execute app JS on existing DOM (simulates page reload)
    const appJs = fs.readFileSync(
      path.resolve(__dirname, "..", "..", "js", "app.js"),
      "utf-8"
    );
    const scriptEl = this.document.createElement("script");
    scriptEl.textContent = appJs;
    this.document.body.appendChild(scriptEl);
  }

  findTodoItem(title) {
    const labels = this.document.querySelectorAll(".todo-list li label");
    for (const label of labels) {
      if (label.textContent === title) return label.closest("li");
    }
    return null;
  }
}

module.exports = { TodoWorld };

