/**
 * TodoMVC application
 *
 * @planks("When the user adds a new todo {string}")
 * @planks("Then the todo list displays {string}")
 * @planks("Then the todo list does not display {string}")
 * @planks("Then the todo list has {int} item")
 * @planks("Then the todo list has {int} items")
 * @planks("Then the main section is hidden")
 * @planks("Then the main section is visible")
 * @planks("Then the footer is hidden")
 * @planks("Then the footer is visible")
 * @planks("When the user marks {string} as complete")
 * @planks("When the user marks {string} as active")
 * @planks("Then {string} is marked as completed")
 * @planks("Then {string} is not marked as completed")
 * @planks("When the user clicks the toggle-all checkbox")
 * @planks("Then the toggle-all checkbox is checked")
 * @planks("Then the toggle-all checkbox is not checked")
 * @planks("When the user double-clicks the label for {string}")
 * @planks("Then {string} is in editing mode")
 * @planks("Then {string} is not in editing mode")
 * @planks("When the user changes the edit value to {string} and presses Enter")
 * @planks("When the user changes the edit value to {string} and clicks outside")
 * @planks("When the user changes the edit value to {string} and presses Escape")
 * @planks("When the user clears the edit value and presses Enter")
 * @planks("Then the edit field for {string} contains {string}")
 * @planks("Then the edit field for {string} is focused")
 * @planks("When the user clicks {string}")
 * @planks("Then the clear completed button is hidden")
 * @planks("Then the counter shows {string}")
 */
(function () {
  "use strict";

  var STORAGE_KEY = "todos-vanilla";
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  function getTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function setTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function updateToggleAll() {
    var todos = getTodos();
    var toggleAll = document.querySelector("#toggle-all");
    if (todos.length === 0) {
      toggleAll.checked = false;
    } else {
      toggleAll.checked = todos.every(function (t) { return t.completed; });
    }
  }

  function updateCounter() {
    var todos = getTodos();
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var countEl = document.querySelector(".todo-count");
    var word = activeCount === 1 ? "item" : "items";
    countEl.innerHTML = "<strong>" + activeCount + "</strong> " + word + " left";
  }

  function updateClearCompleted() {
    var todos = getTodos();
    var hasCompleted = todos.some(function (t) { return t.completed; });
    var btn = document.querySelector(".clear-completed");
    btn.style.display = hasCompleted ? "" : "none";
  }

  function render() {
    var todos = getTodos();
    var list = document.querySelector(".todo-list");
    var main = document.querySelector(".main");
    var footer = document.querySelector(".footer");

    // Clear list
    list.innerHTML = "";

    // Render todos
    for (var i = 0; i < todos.length; i++) {
      var li = document.createElement("li");
      li.setAttribute("data-id", todos[i].id);
      if (todos[i].completed) {
        li.className = "completed";
      }

      var viewDiv = document.createElement("div");
      viewDiv.className = "view";

      var toggle = document.createElement("input");
      toggle.className = "toggle";
      toggle.type = "checkbox";
      toggle.checked = todos[i].completed;

      var label = document.createElement("label");
      label.textContent = todos[i].title;

      var destroyBtn = document.createElement("button");
      destroyBtn.className = "destroy";

      viewDiv.appendChild(toggle);
      viewDiv.appendChild(label);
      viewDiv.appendChild(destroyBtn);

      var editInput = document.createElement("input");
      editInput.className = "edit";
      editInput.value = todos[i].title;

      li.appendChild(viewDiv);
      li.appendChild(editInput);
      list.appendChild(li);
    }

    // Show/hide main and footer
    if (todos.length === 0) {
      main.style.display = "none";
      footer.style.display = "none";
    } else {
      main.style.display = "";
      footer.style.display = "";
    }

    updateToggleAll();
    updateCounter();
    updateClearCompleted();
  }

  function addTodo(title) {
    var todos = getTodos();
    todos.push({
      id: Date.now().toString(),
      title: title,
      completed: false,
    });
    setTodos(todos);
    render();
  }

  function onNewTodoKeydown(event) {
    if (event.keyCode !== ENTER_KEY) return;
    var input = event.target;
    var title = input.value.trim();
    if (title === "") return;
    addTodo(title);
    input.value = "";
  }

  function findTodoById(id) {
    var todos = getTodos();
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return i;
    }
    return -1;
  }

  function onToggleClick(event) {
    var li = event.target.closest("li");
    var id = li.getAttribute("data-id");
    var idx = findTodoById(id);
    if (idx === -1) return;
    var todos = getTodos();
    todos[idx].completed = !todos[idx].completed;
    setTodos(todos);
    render();
  }

  function onToggleAllClick() {
    var toggleAll = document.querySelector("#toggle-all");
    var todos = getTodos();
    var newState = toggleAll.checked;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = newState;
    }
    setTodos(todos);
    render();
  }

  function onDoubleClick(event) {
    var label = event.target;
    if (label.tagName !== "LABEL") return;
    var li = label.closest("li");
    li.classList.add("editing");
    var editInput = li.querySelector(".edit");
    editInput.focus();
  }

  function onEditKeydown(event) {
    var editInput = event.target;
    var li = editInput.closest("li");
    var id = li.getAttribute("data-id");
    var idx = findTodoById(id);
    if (idx === -1) return;

    if (event.keyCode === ENTER_KEY) {
      var newTitle = editInput.value.trim();
      if (newTitle === "") {
        // Destroy todo
        var todos = getTodos();
        todos.splice(idx, 1);
        setTodos(todos);
        render();
      } else {
        var todos = getTodos();
        todos[idx].title = newTitle;
        setTodos(todos);
        li.classList.remove("editing");
        render();
      }
    } else if (event.keyCode === ESCAPE_KEY) {
      // Cancel - revert the edit input to original title
      var todos = getTodos();
      editInput.value = todos[idx].title;
      li.classList.remove("editing");
    }
  }

  function onEditBlur(event) {
    var editInput = event.target;
    var li = editInput.closest("li");
    if (!li.classList.contains("editing")) return;
    var id = li.getAttribute("data-id");
    var idx = findTodoById(id);
    if (idx === -1) return;
    var newTitle = editInput.value.trim();
    if (newTitle === "") {
      var todos = getTodos();
      todos.splice(idx, 1);
      setTodos(todos);
      render();
    } else {
      var todos = getTodos();
      todos[idx].title = newTitle;
      setTodos(todos);
      li.classList.remove("editing");
      render();
    }
  }

  function onClearCompletedClick() {
    var todos = getTodos().filter(function (t) { return !t.completed; });
    setTodos(todos);
    render();
  }

  // Delegated event listeners on the todo list
  var todoList = document.querySelector(".todo-list");

  // Toggle individual todo
  todoList.addEventListener("change", function (event) {
    if (event.target.className === "toggle") {
      onToggleClick(event);
    }
  });

  // Double-click to edit
  todoList.addEventListener("dblclick", function (event) {
    onDoubleClick(event);
  });

  // Edit keydown (Enter to save, Escape to cancel)
  todoList.addEventListener("keydown", function (event) {
    if (event.target.className === "edit") {
      onEditKeydown(event);
    }
  });

  // Edit blur (save on blur)
  todoList.addEventListener("blur", function (event) {
    if (event.target.className === "edit") {
      onEditBlur(event);
    }
  }, true);

  // New todo input
  var newTodoInput = document.querySelector(".new-todo");
  if (newTodoInput) {
    newTodoInput.addEventListener("keydown", onNewTodoKeydown);
  }

  // Toggle-all
  var toggleAll = document.querySelector("#toggle-all");
  if (toggleAll) {
    toggleAll.addEventListener("click", onToggleAllClick);
  }

  // Clear completed
  var clearCompleted = document.querySelector(".clear-completed");
  if (clearCompleted) {
    clearCompleted.addEventListener("click", onClearCompletedClick);
  }

  render();
})();

