  if (this.localStorage) {
    const data = this.localStorage.getItem("todos-vanilla");
    if (data) oldStorage["todos-vanilla"] = data;
  }

  const window = new Window();
  this.window = window;
  this.document = window.document;
  this.localStorage = window.localStorage;

